// junta as 2 paginas, dedupe, filtra: pipeline 2, ultimos 3 dias, e (rastreio 100% vazio OU tier vazio)
// resolve tier por REGRA aqui mesmo: agente de parcerias/indicacao -> Agentes; criacao manual -> Adicao manual
const p1 = $('Deals p1').first().json.data || [];
let p2 = [];
try { p2 = $('Deals p2').first().json.data || []; } catch (e) {}
const TRACK = ["babc9dc70b0254caf284ed9ac6904531bdd2247b", "fbef9289bf09467ab894d55a0da0785f7d131c92", "1c61ffb7c5c72afcda0aa03ec34a699098fa82a3", "ce55f714284ac86b8463c672880636db6568e5f8", "a75682beeaee346f25771516d2f23cdaf4b7745c", "921ee7657991cd504cd859f5b8fd0b47bb8b2ff6"];
const seen = new Set(); const corte = Date.now() - 3*24*60*60*1000;
const vazio = v => v === null || v === undefined || v === '';
const out = [];
for (const d of [...p1, ...p2]) {
  if (seen.has(d.id)) continue; seen.add(d.id);
  if (d.pipeline_id !== 2) continue;
  if (new Date(d.add_time).getTime() < corte) continue;
  const cf = d.custom_fields || {};
  const falta_utm = TRACK.every(k => vazio(cf[k]));
  const falta_tier = vazio(cf['346353ade45adcb68850667587de1da11b3bdadd']);
  if (!falta_utm && !falta_tier) continue;
  let tier_regra = '';
  if (falta_tier) {
    if (!vazio(cf['b603f8b2476b87146d418bd7692ca4d2a41f71a1']) || cf['5eb405ac4c55fa7ed5acf14c3af542d0a72aaeda'] === 1582) tier_regra = 'Agentes';
    else if (d.origin === 'ManuallyCreated') tier_regra = 'Adição manual';
  }
  if (!d.person_id && !(falta_tier && tier_regra)) continue;
  out.push({ json: { deal_id: d.id, person_id: d.person_id || '', falta_utm, falta_tier, tier_regra } });
}
return out;

// pareia por indice com o filtro e extrai email/fone
const base = $('Filtra sem origem').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const b = base[i].json;
  const resp = items[i].json.data || items[i].json || {};
  const emails = resp.emails || resp.email || [];
  const em = ((emails.find && emails.find(e => e && e.primary)) || emails[0] || {}).value || '';
  const email = (em && em.includes('@')) ? em.trim().toLowerCase() : '';
  const phones = resp.phones || resp.phone || [];
  const ph = ((phones.find && phones.find(p => p && p.primary)) || phones[0] || {}).value || '';
  const fone8 = String(ph).replace(/\D/g, '').slice(-8);
  if (!email && fone8.length < 8 && !(b.falta_tier && b.tier_regra)) continue;
  out.push({ json: { ...b, email, fone8 } });
}
return out;

// UTM via RD (como antes) + tier: regra > RD cf_tier_atual; o que sobrar vai pro desvio do Supabase
const SRC_OK = ['direto','google','outros','meta','cardapioweb_com','bing','chatgpt','seo','portal_cardapioweb','brave','yahoo','claude','wpp','youtube','ig','tiktok','rd_station_link_na_bio','fb','an'];
const MED_OK = ['direct','organic','paid','paidsearch','referral','social'];
const DERIVA = {direto:'direct', bing:'organic', brave:'organic', yahoo:'organic', seo:'organic',
  meta:'paid', chatgpt:'referral', claude:'referral', cardapioweb_com:'referral', portal_cardapioweb:'referral'};
const MAPA = {'direto':'direto','meta':'meta','facebook':'meta','fb':'fb','ig':'ig','instagram':'ig',
  'www.bing.com':'bing','bing':'bing','search.brave.com':'brave','br.search.yahoo.com':'yahoo',
  'chatgpt.com':'chatgpt','claude.ai':'claude','cardapioweb.com':'cardapioweb_com',
  'www.cardapioweb.com':'cardapioweb_com','lp.cardapioweb.com':'cardapioweb_com',
  'portal.cardapioweb.com':'portal_cardapioweb','rd_station_link_na_bio':'rd_station_link_na_bio',
  'wpp':'wpp','whatsapp':'wpp','www.youtube.com':'youtube','youtube':'youtube','tiktok':'tiktok','seo':'seo'};
const TIER_MAP = {'1':'Tier 1','2':'Tier 2','3.1':'Tier 3.1','3.2':'Tier 3.2','4':'Tier 4','5':'Tier 5'};
const base = $('Extrai email').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const b = base[i].json;
  const r = items[i].json; const status = r.statusCode || (r.body ? 200 : 0);
  const c = (status === 200) ? (r.body || r) : {};
  let fonte = '', med = '';
  if (b.falta_utm && status === 200) {
    const raw = String(c.cf_utm_source || '').toLowerCase().trim();
    const gclid = c.cf_gclid || ''; const fbclid = c.cf_fbclid || '';
    const tags = (c.tags || []).map(t => String(t).toLowerCase());
    if (raw) {
      if (/^[0-9]{12,}$/.test(raw)) fonte = 'meta';
      else if (raw.includes('google')) fonte = 'google';
      else fonte = MAPA[raw] || 'outros';
    } else if (fbclid) fonte = 'meta';
    else if (gclid) fonte = 'google';
    else if (tags.some(t => t.includes('origem seo'))) fonte = 'seo';
    else if (tags.some(t => t.includes('origem google'))) fonte = 'google';
    if (fonte && !SRC_OK.includes(fonte)) fonte = '';
    if (fonte) {
      med = String(c.cf_utm_medium || '').trim();
      if (!(med && MED_OK.includes(med))) { med = DERIVA[fonte] || ''; if (!med && fonte === 'google' && (c.cf_gclid||'')) med = 'paidsearch'; }
    }
  }
  let tier = '';
  if (b.falta_tier) {
    tier = b.tier_regra || '';
    if (!tier && status === 200) {
      const rt = String(c.cf_tier_atual || '').trim();
      if (TIER_MAP[rt]) tier = TIER_MAP[rt];
    }
  }
  const precisa_supa = !!(b.falta_tier && !tier && b.fone8 && b.fone8.length === 8);
  const escreve_utm = !!(b.falta_utm && fonte);
  if (!escreve_utm && !tier && !precisa_supa) continue;
  out.push({ json: { deal_id: b.deal_id, escreve_utm, fonte, med,
    camp: escreve_utm ? String(c.cf_utm_campaign || '').slice(0, 250) : '',
    cont: escreve_utm ? String(c.cf_utm_content || '').slice(0, 250) : '',
    gclid: escreve_utm ? String(c.cf_gclid || '').slice(0, 250) : '',
    fbclid: escreve_utm ? String(c.cf_fbclid || '').slice(0, 250) : '',
    tier, precisa_supa, fone8: b.fone8 } });
}
return out;

const TIER_MAP = {'1':'Tier 1','2':'Tier 2','3.1':'Tier 3.1','3.2':'Tier 3.2','4':'Tier 4','5':'Tier 5'};
const t = TIER_MAP[String($json.tier || '').trim()] || '';
return { json: { deal_id: $('Contexto tier').item.json.deal_id, tier: t } };
